[Form]
public class METCustomerMDFInquiry extends FormRun
{

    private CustAccount custAccountVal;
    private InventSiteId siteIdVal;
    private InventLocationId locationIdVal;
    private CustInvoiceId custInvoiceIdVal;
    private SalesIdBase salesIdVal;
    private MetShipmentId shipmentIdVal;
    private METConsolidationMethodEDT consolidationMethodEDTVal;
    private METApplicationMethodEDT applicationMethodEDTVal;
    private METCustomerMDFInquiryTempTable customerMDFInquiryTmp;

    #LOCALMACRO.CurrentList
        custAccountVal,
        siteIdVal,
        locationIdVal,
        custInvoiceIdVal,
        salesIdVal,
        shipmentIdVal,
        consolidationMethodEDTVal,
        applicationMethodEDTVal
    #ENDMACRO




}

private void initParameters()
{
    xSysLastValue::getLast(this);

    CustAccount.text(custAccountVal);
    Site.text(siteIdVal);
    Warehouse.text(locationIdVal);
    TaxInvoice.text(custInvoiceIdVal);
    SalesOrders.text(salesIdVal);
    ShipmentId.text(shipmentIdVal);
    ConsolidationMethod.text(enum2Str(consolidationMethodEDTVal));
    ApplicationMethod.text(enum2Str(applicationMethodEDTVal));

}

public void modified()
{
    str invoiceId = TaxInvoice.valueStr();
    CustInvoiceJour invoiceJour;
    METSalesOrderShipmentLoadHeader shipment;

    // Fetch invoice record
    select firstOnly invoiceJour
        where invoiceJour.InvoiceId == invoiceId;

    if (invoiceJour)
    {
        SalesId salesId = invoiceJour.SalesId;
        salesTable = SalesTable::find(salesId);

        // Corrected: Match shipment.SalesId to salesTable.SalesId
        select firstOnly shipment
            where shipment.SiteId == salesTable.InventSiteId
            && shipment.CustAccount == salesTable.CustAccount
            && shipment.Warehouse == salesTable.InventLocationId;

        if (shipment)
        {
            ShipmentId.text(shipment.ShipmentId);
        }
    }

    //super();
}

public void lookup()
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(CustTable), CustAccount);
    Query lookupQuery = new Query();

    // Add CustTable as primary data source
    QueryBuildDataSource custDS = lookupQuery.addDataSource(tableNum(CustTable));

    // Join DirPartyTable to get the customer name
    QueryBuildDataSource partyDS = custDS.addDataSource(tableNum(DirPartyTable));
    partyDS.relations(true); // Use table relations
    partyDS.joinMode(JoinMode::InnerJoin);

    // Add fields to display
    sysTableLookup.addLookupField(fieldNum(CustTable, AccountNum));
    sysTableLookup.addLookupField(fieldNum(DirPartyTable, Name));

    // Bind and show lookup
    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.performFormLookup();
}

public boolean modified()
{
    boolean ret;
    ret = super();

    CustTable custTableLocal = CustTable::find(CustAccount.valueStr());
    DirPartyTable dirPartyTable;

    if (custTableLocal)
    {
        dirPartyTable = DirPartyTable::findRec(custTableLocal.Party);
        CustName.text(dirPartyTable.Name);
    }
    else
    {
        CustName.text("");
    }

    return ret;
}

public void lookup()
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(InventSite), Site);
    Query lookupQuery = new Query();

    // Build the query
    QueryBuildDataSource siteIdDS = lookupQuery.addDataSource(tableNum(InventSite));

    // Add fields to display in the lookup
    sysTableLookup.addLookupField(fieldNum(InventSite, SiteId));
    sysTableLookup.addLookupField(fieldNum(InventSite, Name));

    // Bind the query to the control
    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.performFormLookup();
}

public void lookup()
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(InventLocation), Warehouse);
    Query lookupQuery = new Query();

    // Add InventLocation as the main data source
    QueryBuildDataSource locationDS = lookupQuery.addDataSource(tableNum(InventLocation));

    // Filter by selected site
    locationDS.addRange(fieldNum(InventLocation, InventSiteId)).value(queryValue(Site.valueStr()));

    // Add fields to show in the lookup
    sysTableLookup.addLookupField(fieldNum(InventLocation, InventLocationId));
    sysTableLookup.addLookupField(fieldNum(InventLocation, Name));

    // Bind query and show lookup
    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.performFormLookup();
}

public void lookup()
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(CustInvoiceJour), TaxInvoice);
    Query lookupQuery = new Query();

    // Add CustInvoiceJour as primary data source
    QueryBuildDataSource invoiceDS = lookupQuery.addDataSource(tableNum(CustInvoiceJour));

    // Join SalesTable to filter by customer, site, warehouse, and status
    QueryBuildDataSource salesDS = invoiceDS.addDataSource(tableNum(SalesTable));
    salesDS.relations(true); // CustInvoiceJour.SalesId → SalesTable.SalesId
    salesDS.joinMode(JoinMode::InnerJoin);

    // Filter: Only show invoices where sales order status is Invoiced
    salesDS.addRange(fieldNum(SalesTable, SalesStatus)).value(queryValue(SalesStatus::Invoiced));

    // Filter by selected customer
    if (CustAccount.valueStr())
    {
        salesDS.addRange(fieldNum(SalesTable, CustAccount)).value(queryValue(CustAccount.valueStr()));
    }

    // Filter by selected site
    if (Site.valueStr())
    {
        salesDS.addRange(fieldNum(SalesTable, InventSiteId)).value(queryValue(Site.valueStr()));
    }

    // Filter by selected warehouse
    if (Warehouse.valueStr())
    {
        salesDS.addRange(fieldNum(SalesTable, InventLocationId)).value(queryValue(Warehouse.valueStr()));
    }

    // Add fields to display in the lookup
    sysTableLookup.addLookupField(fieldNum(CustInvoiceJour, InvoiceId));
    sysTableLookup.addLookupField(fieldNum(CustInvoiceJour, InvoiceDate));
    sysTableLookup.addLookupField(fieldNum(CustInvoiceJour, SalesId));

    // Bind and show lookup
    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.performFormLookup();
}

public boolean modified()
{
    boolean ret;
    ret = super();

    CustInvoiceJour invoiceJour;
    // Get selected invoice
    select firstOnly invoiceJour
        where invoiceJour.InvoiceId == TaxInvoice.valueStr();

    SalesOrders.text(invoiceJour.SalesId);

    return ret;
}

public void lookup()
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(SalesTable), SalesOrders);
    Query lookupQuery = new Query();

    // Add SalesTable as the main data source
    QueryBuildDataSource salesDS = lookupQuery.addDataSource(tableNum(SalesTable));

    // Filter: Only show sales orders with status = Invoiced
    salesDS.addRange(fieldNum(SalesTable, SalesStatus)).value(queryValue(SalesStatus::Invoiced));

    // Add fields to display in the lookup
    sysTableLookup.addLookupField(fieldNum(SalesTable, SalesId));
    sysTableLookup.addLookupField(fieldNum(SalesTable, CustAccount));
    sysTableLookup.addLookupField(fieldNum(SalesTable, DeliveryDate));

    // Bind and show lookup
    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.performFormLookup();
}

public void lookup()
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(METSalesOrderShipmentLoadHeader), ShipmentId);
    Query lookupQuery = new Query();

    // Add MetShipmentTable as primary data source
    QueryBuildDataSource shipmentDS = lookupQuery.addDataSource(tableNum(METSalesOrderShipmentLoadHeader));

    // Join SalesTable to filter by customer
    QueryBuildDataSource salesDS = shipmentDS.addDataSource(tableNum(SalesTable));
    salesDS.relations(true); // MetShipmentTable.SalesId → SalesTable.SalesId
    salesDS.joinMode(JoinMode::InnerJoin);

    // Filter by selected customer
    if (CustAccount.valueStr())
    {
        salesDS.addRange(fieldNum(SalesTable, CustAccount)).value(queryValue(CustAccount.valueStr()));
        salesDS.addRange(fieldNum(SalesTable, InventSiteId)).value(queryValue(Site.valueStr()));
        salesDS.addRange(fieldNum(SalesTable, InventLocationId)).value(queryValue(Warehouse.valueStr()));
    }

    // Add fields to display
    sysTableLookup.addLookupField(fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId));

    // Bind and show lookup
    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.performFormLookup();
}

public void lookup()
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(MetCustomerMdfTable), ConsolidationMethod);
    Query lookupQuery = new Query();

    QueryBuildDataSource setupDS = lookupQuery.addDataSource(tableNum(MetCustomerMdfTable));

    // Filter by Customer
    if (CustAccount.valueStr())
    {
        setupDS.addRange(fieldNum(MetCustomerMdfTable, CustAccount)).value(queryValue(CustAccount.valueStr()));
    }

    // Filter by Site
    if (Site.valueStr())
    {
        setupDS.addRange(fieldNum(MetCustomerMdfTable, InventSiteId)).value(queryValue(Site.valueStr()));
    }

    // Filter by Warehouse
    if (Warehouse.valueStr())
    {
        setupDS.addRange(fieldNum(MetCustomerMdfTable, InventLocationId)).value(queryValue(Warehouse.valueStr()));
    }

    // Add enum field to lookup
    sysTableLookup.addLookupField(fieldNum(MetCustomerMdfTable, ConsolidationMethodEDT));

    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.performFormLookup();
}

